import { useState } from "react";
import type { GalleryImageView } from "./types";

interface GalleryImageProps {
	image: GalleryImageView;
	sizes: string;
	className?: string;
	priority?: boolean;
	contain?: boolean;
	/** Absolute fill (cropped cells) or natural height (masonry). */
	fill?: boolean;
}

/**
 * Blur-up image that keeps the aspect ratio from the source file.
 * The tiny WebP placeholder is generated by Astro at build time.
 */
export default function GalleryImage({
	image,
	sizes,
	className = "",
	priority = false,
	contain = false,
	fill = true,
}: GalleryImageProps) {
	const [loaded, setLoaded] = useState(false);

	// Images can finish loading before React hydrates, so `onLoad` alone can
	// leave them invisible forever. The ref callback checks the cached state
	// during commit, before the browser paints.
	const handleRef = (node: HTMLImageElement | null) => {
		if (node?.complete) setLoaded(true);
	};

	return (
		<span
			className={`block overflow-hidden ${
				contain ? "bg-transparent" : "bg-raised"
			} ${fill ? "absolute inset-0" : "relative w-full"}`}
		>
			{!contain && (
				<span
					aria-hidden="true"
					className={`absolute inset-0 scale-110 bg-cover bg-center blur-xl transition-opacity duration-500 ${
						loaded ? "opacity-0" : "opacity-90"
					}`}
					style={{ backgroundImage: `url(${image.blurUrl})` }}
				/>
			)}
			<img
				ref={handleRef}
				src={image.src}
				srcSet={image.srcSet}
				sizes={sizes}
				alt={image.alt}
				width={image.width}
				height={image.height}
				loading={priority ? "eager" : "lazy"}
				decoding="async"
				fetchPriority={priority ? "high" : "auto"}
				onLoad={() => setLoaded(true)}
				draggable={false}
				className={`relative transition-opacity duration-500 ${
					fill ? "size-full" : "block h-auto w-full"
				} ${contain ? "object-contain" : "object-cover"} ${
					loaded ? "opacity-100" : "opacity-0"
				} ${className}`}
				style={{ objectPosition: image.focalPoint }}
			/>
		</span>
	);
}
